  [{ week: '2026-03-02', visits: 1, seen: 1, walkouts: 0, median_wait_min: 12 }]);
eq('Sunday belongs to the week starting the Monday before', weekOf('2026-03-08 10:00'), '2026-03-02');
eq('Monday starts its own week', weekOf('2026-03-09 10:00'), '2026-03-09');
eq('week crossing a year boundary', weekOf('2027-01-01 09:00'), '2026-12-28');
eq('weeks print in date order', summarize(csv('1,2026-03-10 09:00,2026-03-10 09:05', '2,2026-03-03 09:00,2026-03-03 09:05')).map((w) => w.week),
  ['2026-03-02', '2026-03-09']);

// walkouts
eq('walkouts counted as visits, not as seen', summarize(csv('1,2026-03-04 09:00,2026-03-04 09:10', '2,2026-03-04 09:05,', '3,2026-03-04 09:06,2026-03-04 09:36')),
  [{ week: '2026-03-02', visits: 3, seen: 2, walkouts: 1, median_wait_min: 20 }]);
eq('all-walkout week has null median', summarize(csv('1,2026-03-04 09:00,')),
  [{ week: '2026-03-02', visits: 1, seen: 0, walkouts: 1, median_wait_min: null }]);
eq('identical rows are two visits', summarize(csv('1,2026-03-04 09:00,2026-03-04 09:10', '1,2026-03-04 09:00,2026-03-04 09:10'))[0].visits, 2);

// time arithmetic is wall-clock, whatever the machine zone
eq('wait across the US DST night (2026-03-08)', minutes('2026-03-08 01:50', '2026-03-08 03:10'), 80);
for (const tz of ['America/Chicago', 'Pacific/Auckland']) {
