    { env: { ...process.env, TZ: tz }, encoding: 'utf8' }).trim();
  eq(`DST-night waits under TZ=${tz}`, out, '80 40');
}

// input tolerance and validation
eq('CRLF, BOM and blank lines tolerated', summarize(parse('﻿id,signed_in,seen_at\r\n1,2026-03-04 09:00,2026-03-04 09:12\r\n\r\n')),
