// assign.mjs — who works when, under POLICY.md.
//
// Shape: (1) up-front refusals that name the rules that clash; (2) a day-by-day search in which
// every rule is hard and every prune is a necessary condition, so an exhausted search is a proof;
// (3) integer targets drawn by a lottery seeded from the period (never from names or file order),
// so rounding favours nobody in the long run. "Gave up" (budget) is reported apart from "impossible".
import { days, isWeekend } from './calendar.mjs';
import { bounds, checkRota, MAX_RUN } from './policy.mjs';
import { validatePeople } from './people.mjs';

export const NODE_LIMIT = 2_000_000;
// Jittered restarts: tie noise of 0.3 on the urgency score, then 40 short tries before the long ones.
// Tuned on two seed-7/seed-11 teams that gave up with near-zero jitter (both are feasible).
const JIT = 0.3, SHORT = 40, SHORT_LIM = 10000;
const EXHAUSTED = 'no rota can follow POLICY.md: rules 1–5 cannot all be met for this team and period (exhaustive search; no single named clash)';

