// Integers within [lo, hi] summing to `total`, each as near its share as possible; the leftover
// units go by systematic lottery (each share's fraction is its chance), so nobody is favoured.
export function lottery(values, lo, hi, total, rnd) {
  const fl = values.map((v, i) => Math.min(hi[i], Math.max(lo[i], Math.floor(v))));
  const fr = values.map((v, i) => (fl[i] < hi[i] ? Math.max(0, Math.min(1, v - fl[i])) : 0));
  let left = total - fl.reduce((a, b) => a + b, 0);
  const F = fr.reduce((a, b) => a + b, 0);
  if (left > 0 && F > 0) {
    const step = F / left;
    let u = rnd() * step, acc = 0;
    for (let i = 0; i < values.length && left > 0; i++) {
      acc += fr[i];
      if (acc > u) { fl[i]++; left--; u += step; }
    }
  }
  // Whatever rounding couldn't place (clipped shares) goes to whoever has room, nearest share first.
  for (let guard = 0; left !== 0 && guard < 10000; guard++) {
    const dir = Math.sign(left);
    let best = -1, bestGap = Infinity;
    for (let i = 0; i < values.length; i++) {
      if (dir > 0 ? fl[i] >= hi[i] : fl[i] <= lo[i]) continue;
      const gap = dir * (fl[i] - values[i]);
      if (gap < bestGap) { bestGap = gap; best = i; }
    }
    if (best < 0) break;
    fl[best] += dir; left -= dir;
  }
  return fl;
}

// Most days a person can work in days [d, n) given a current run r, with weights (1 = all days,
// or weekend-only). Exact DP over rule 2 and rule 3. Indexed [d * (MAX_RUN+1) + r].
// `must` (optional): days that have to be worked (forced days); resting on one is not allowed.
// A negative entry means no lawful schedule exists from that state.
const NO = -30000;
function maxTable(avail, wt, n, must = null) {
  const R = MAX_RUN + 1, f = new Int32Array((n + 1) * R);
