// people.mjs — load and validate the team file.
import { readFileSync } from 'node:fs';

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (s) => DATE.test(s) && new Date(`${s}T00:00:00Z`).toISOString().slice(0, 10) === s;

// Throws on anything the policy can't be applied to. Returns people with fte a number and leave a Set.
export function validatePeople(raw) {
  if (!Array.isArray(raw) || raw.length === 0) throw new Error('team file must be a non-empty list of people');
  const seen = new Set();
  return raw.map((p) => {
    const who = JSON.stringify(p);
    if (!p || typeof p.name !== 'string' || !p.name.trim()) throw new Error(`person without a name: ${who}`);
    if (seen.has(p.name)) throw new Error(`duplicate name: ${p.name}`);
    seen.add(p.name);
    if (!['nurse', 'aide'].includes(p.role)) throw new Error(`${p.name}: role must be "nurse" or "aide", got ${JSON.stringify(p.role)}`);
    // Missing fte is an error, not a default of 1: a default nobody chose falls on whoever it doesn't fit.
    if (typeof p.fte !== 'number' || !Number.isFinite(p.fte) || p.fte < 0 || p.fte > 1)
      throw new Error(`${p.name}: fte must be a number from 0 to 1 (1 = full time), got ${JSON.stringify(p.fte)}`);
    const leave = p.leave instanceof Set ? [...p.leave] : p.leave ?? [];
    if (!Array.isArray(leave)) throw new Error(`${p.name}: leave must be a list of dates`);
    for (const d of leave) if (!realDate(d)) throw new Error(`${p.name}: bad leave date ${JSON.stringify(d)}`);
    return { ...p, fte: p.fte, leave: new Set(leave) };
  });
}

export function loadPeople(path) {
  return validatePeople(JSON.parse(readFileSync(path, 'utf8')));
}

