// policy.mjs — POLICY.md as code: the shares each person is owed, and an independent checker.
// The checker doesn't know how a rota was made; the tests judge every rota with it.
import { days, isWeekend } from './calendar.mjs';

export const MAX_RUN = 5;          // rule 3
export const TOTAL_SLACK = 2;      // rule 4
export const WEEKEND_SLACK = 1.5;  // rule 5
const EPS = 1e-9;

// Rule 4/5 shares. weight = fte × (days not on leave) / DAYS, shares of 2×DAYS and 2×(weekend days).
export function shares(people, start, n) {
  const ds = days(start, n);
  const wkDays = ds.filter(isWeekend).length;
  const w = people.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n);
  const W = w.reduce((a, b) => a + b, 0);
  if (!(W > 0)) throw new Error('rule 4: nobody has any weight (every fte is 0 or everyone is on leave)');
  return people.map((p, i) => ({ name: p.name, weight: w[i], total: (2 * n * w[i]) / W, weekend: (2 * wkDays * w[i]) / W }));
}

// Integer ranges the policy allows: |got − share| ≤ slack.
export function bounds(people, start, n) {
  return shares(people, start, n).map((s) => ({
    ...s,
    lo: Math.max(0, Math.ceil(s.total - TOTAL_SLACK - EPS)), hi: Math.floor(s.total + TOTAL_SLACK + EPS),
    wlo: Math.max(0, Math.ceil(s.weekend - WEEKEND_SLACK - EPS)), whi: Math.floor(s.weekend + WEEKEND_SLACK + EPS),
  }));
}

export function tally(people, rota) {
  const t = Object.fromEntries(people.map((p) => [p.name, { total: 0, weekend: 0 }]));
  for (const [day, pair] of Object.entries(rota)) for (const name of pair) if (t[name]) { t[name].total++; if (isWeekend(day)) t[name].weekend++; }
  return t;
}

// Every breach of rules 1–5, as strings. Empty list = lawful.
export function checkRota(people, start, n, rota) {
  const bad = [];
  const ds = days(start, n);
  const byName = new Map(people.map((p) => [p.name, p]));
  const extra = Object.keys(rota).filter((d) => !ds.includes(d));
  if (extra.length) bad.push(`rota has days outside the period: ${extra.join(', ')}`);
  const run = Object.fromEntries(people.map((p) => [p.name, 0]));
  for (const d of ds) {
    const pair = rota[d];
    if (!Array.isArray(pair) || pair.length !== 2 || new Set(pair).size !== 2) { bad.push(`rule 1: ${d} does not have exactly two different people`); }
    const on = new Set(Array.isArray(pair) ? pair : []);
    for (const name of on) {
      const p = byName.get(name);
      if (!p) { bad.push(`${d}: unknown person ${name}`); continue; }
      if (p.leave.has(d)) bad.push(`rule 2: ${name} works ${d}, a leave day`);
    }
    if (![...on].some((x) => byName.get(x)?.role === 'nurse')) bad.push(`rule 1: no nurse on ${d}`);
    for (const p of people) {
      const r = on.has(p.name) ? run[p.name] + 1 : 0;
      run[p.name] = r;
      if (r === MAX_RUN + 1) bad.push(`rule 3: ${p.name} works more than ${MAX_RUN} days in a row (to ${d})`);
    }
  }
  const t = tally(people, rota);
  for (const s of shares(people, start, n)) {
    const g = t[s.name];
    if (Math.abs(g.total - s.total) > TOTAL_SLACK + EPS) bad.push(`rule 4: ${s.name} has ${g.total} shifts, share ${s.total.toFixed(2)}`);
    if (Math.abs(g.weekend - s.weekend) > WEEKEND_SLACK + EPS) bad.push(`rule 5: ${s.name} has ${g.weekend} weekend shifts, share ${s.weekend.toFixed(2)}`);
  }
  return bad;
}

