  ok('checker: rule 3, five in a row is allowed', !checkRota(team, start, n, five).some((b) => /rule 3/.test(b)));
  const seven = structuredClone(six); seven['2026-11-08'] = ['N1', 'A1']; // N1 all 7 days, share ≈ 4.9
  ok('checker: rule 4, too many shifts', checkRota(team, start, n, seven).some((b) => /rule 4: N1/.test(b)));
