  const d = mkdtempSync(join(tmpdir(), 'mod-'));
  const rep = ['reporter,date,reported,reason', 'a,2026-07-06,v,x', 'b,2026-07-06,v,x', 'c,2026-07-06,v,x', 'j,2026-07-13,v,x', '', 'a,2026-08-30,w,x'].join('\r\n');
